batterySource:
// generic-rag-chunking P-011 R-27 live battery: work-item search (the working-tree
// searchWorkItems behind work_items:search, default options) against the live
// operator DB after the work_items chunk sync + embed. Sample: N non-observation
// work items in the workspace whose summary is over 3,500 characters, in
// md5(feature_id) order (fixed pseudo-random, no hand-picking). Query: one sentence
// from the part past the first 2,000 characters that the 4 capped windows still
// cover, whose opening words do not occur in the first 2,000 characters. Records the
// target's rank in the fused result (default limit 50; the tool's shaped page shows
// 20 rows on the trimmed tier and 40 on standard) and, so a miss can be told apart
// from a missing row, the item's rank by its own parent vector alone.
export {};
const base = 'file://~/papercupai-workspace/papercusp/packages/operator-core/lib/';
const { installSearchDefaults } = await import(base + 'search/configure-search-defaults.ts');
const { buildQueryEmbedderResolved } = await import(base + 'agent-tools/search/embedder.ts');
const { WORK_ITEMS_CHUNK_SURFACE } = await import(base + 'search/chunks/registry.ts');
const { searchWorkItems } = await import(base + 'work-items.ts');
const { getOrgPg } = await import('@papercusp/db-org');
installSearchDefaults();

const CUT = 2000;
const N = Number(process.env.N ?? 10);
const WS = 'papercusp-workspace';
const TRIMMED_PAGE = 20;
const sp = WORK_ITEMS_CHUNK_SURFACE.splitter as { size: number; overlap: number };
const covered = sp.size + (WORK_ITEMS_CHUNK_SURFACE.maxChunks! - 1) * (sp.size - sp.overlap);
const resolved = await buildQueryEmbedderResolved({ acquireBudgetMs: 20_000 });
if (!resolved) throw new Error('no query embedder');
const { sql } = getOrgPg();

const items = await sql.unsafe<Array<{ id: string; harness: string; text: string }>>(
  `SELECT w.feature_id AS id, w.harness_slug AS harness, w.summary AS text
     FROM harness_shared.work_items w
    WHERE w.workspace_id = $1 AND w.lane IS DISTINCT FROM 'observation'
      AND length(w.summary) > 3500
      AND EXISTS (SELECT 1 FROM harness_shared.text_chunks c
                   WHERE c.surface = 'work_items' AND c.parent_key = ARRAY[w.harness_slug, w.feature_id]
                     AND c.embedding IS NOT NULL)
    ORDER BY md5(w.feature_id) LIMIT $2`,
  [WS, N * 3],
);

async function search(query: string) {
  for (let attempt = 1; attempt <= 4; attempt++) {
    const r = await searchWorkItems(query, {});
    if (!r.retry && !r.legs?.degraded) return r;
    if (attempt === 4) return r;
    await new Promise((res) => setTimeout(res, Math.max(1000, r.retry?.afterMs ?? 3000)));
  }
  throw new Error('unreachable');
}

const rows: Array<Record<string, unknown>> = [];
for (const t of items) {
  if (rows.filter((r) => !r.skipped).length >= N) break;
  const head = t.text.slice(0, CUT).toLowerCase();
  const region = t.text.slice(CUT, Math.min(t.text.length, covered) - 50);
  const sentences = region
    .split(/(?<=[.!?])\s+|\n+/)
    .map((s) => s.replace(/[`*_#>|[\]()]/g, ' ').replace(/\s+/g, ' ').trim())
    .filter((s) => s.split(' ').length >= 8 && s.length <= 220 && !head.includes(s.toLowerCase().slice(0, 40)));
  const query = sentences[Math.floor(sentences.length * 0.6)];
  if (!query) {
    rows.push({ item: t.id, skipped: 'no usable sentence' });
    continue;
  }
  const vec = `[${(await resolved.embed(query)).join(',')}]`;
  const [ownRank] = await sql.unsafe<Array<{ rank: number }>>(
    `WITH r AS (SELECT feature_id, row_number() OVER (ORDER BY embedding <=> $2::vector) AS rank
                  FROM harness_shared.work_items
                 WHERE workspace_id = $1 AND embedding IS NOT NULL AND lane IS DISTINCT FROM 'observation')
     SELECT rank::int FROM r WHERE feature_id = $3`,
    [WS, vec, t.id],
  );
  const res = await search(query);
  const i = res.items.findIndex((h: { id?: string }) => h.id === t.id);
  rows.push({
    item: t.id,
    chars: t.text.length,
    queryOffset: t.text.indexOf(query.split(' ').slice(0, 4).join(' ')),
    query,
    results: res.items.length,
    returned: i >= 0,
    rank: i + 1,
    withinTrimmedPage: i >= 0 && i < TRIMMED_PAGE,
    ownVectorRank: ownRank?.rank ?? null,
    degraded: res.legs?.degraded ?? null,
    semanticLeg: (res.legs as { semantic?: unknown } | undefined)?.semantic ?? null,
  });
}
for (const r of rows) console.log('ROW', JSON.stringify(r));
const done = rows.filter((r) => !r.skipped);
console.log(
  'SUMMARY',
  JSON.stringify({
    at: new Date().toISOString(),
    n: done.length,
    returned: done.filter((r) => r.returned).length,
    withinTrimmedPage: done.filter((r) => r.withinTrimmedPage).length,
    degraded: done.filter((r) => r.degraded).length,
    ownVectorInTop20: done.filter((r) => typeof r.ownVectorRank === 'number' && (r.ownVectorRank as number) <= 20).length,
  }),
);
process.exit(0);
